parameters.jsCode:
const body = $('Webhook Entrada').item.json.body || {};
const pregunta = body.mensaje || '';
const historial = body.historial || [];
const token = body.token || '';

const metricasRaw = $('Obtener Métricas Dashboard').item.json.data || {};
const recursosData = $('Obtener Detalle Inventario').item.json.data || {};
const ingresosData = $('Obtener Hospitalizados').item.json.data || {};
const labData = $('Obtener Órdenes Lab').item.json.data || {};

let recursos = [];
if (Array.isArray(recursosData)) {
  recursos = recursosData;
} else if (Array.isArray(recursosData.data)) {
  recursos = recursosData.data;
} else if (Array.isArray(recursosData.data?.data)) {
  recursos = recursosData.data.data;
}

const ingresos = Array.isArray(ingresosData) ? ingresosData : (ingresosData.data || []);
const lab = Array.isArray(labData) ? labData : (labData.data || []);

// 1. Inventario en Bodega Central
const medBajos = [];
const medOptimos = [];
const insBajos = [];
const insOptimos = [];
const eqBajos = [];
const eqOptimos = [];

recursos.forEach(r => {
  const cat = (r.categoria || '').toLowerCase();
  const isBajo = Number(r.cantidad || 0) < Number(r.stock_minimo || 0) || r.bajo_minimo === true;
  const line = `- ${r.nombre}: Stock actual ${r.cantidad} ${r.unidad} (Mínimo: ${r.stock_minimo} ${r.unidad})${isBajo ? ` [DÉFICIT: ${Number(r.stock_minimo) - Number(r.cantidad)} ${r.unidad}]` : ' [Óptimo]'}`;

  if (cat.includes('medicamento')) {
    if (isBajo) medBajos.push(line); else medOptimos.push(line);
  } else if (cat.includes('insumo')) {
    if (isBajo) insBajos.push(line); else insOptimos.push(line);
  } else {
    if (isBajo) eqBajos.push(line); else eqOptimos.push(line);
  }
});

const stockCriticoCount = medBajos.length + insBajos.length + eqBajos.length;
const medBajosText = medBajos.length > 0 ? ('  Bajo stock crítico:\n  ' + medBajos.join('\n  ')) : '  Bajo stock: Ninguno.';
const insBajosText = insBajos.length > 0 ? ('  Bajo stock crítico:\n  ' + insBajos.join('\n  ')) : '  Bajo stock: Ninguno.';
const eqBajosText = eqBajos.length > 0 ? ('  Bajo stock crítico:\n  ' + eqBajos.join('\n  ')) : '  Bajo stock: Ninguno.';

// 2. Camas dinámicas
const ocupacionArr = metricasRaw.ocupacion || [];
const p2Disp = ocupacionArr.find(o => o.planta === 2 && o.estado === 'DISPONIBLE')?.total || 0;
const p2Ocup = ocupacionArr.find(o => o.planta === 2 && o.estado === 'OCUPADA')?.total || 0;
const p3Disp = ocupacionArr.find(o => o.planta === 3 && o.estado === 'DISPONIBLE')?.total || 0;
const p3Ocup = ocupacionArr.find(o => o.planta === 3 && o.estado === 'OCUPADA')?.total || 0;

// 3. Hospitalizados con motivos de ingreso clínicos
const internadosLines = ingresos.filter(i => !i.fecha_alta).map(i => {
  const pacNombre = i.paciente?.nombre_completo || 'Paciente';
  const camaCod = i.cama?.codigo || 'Cama s/c';
  const habTipo = i.cama?.habitacion?.tipo || 'Habitación';
  const planta = i.cama?.habitacion?.planta || 2;
  const motivo = i.motivo || 'Observación médica general';
  const med = i.medico?.nombre_completo || 'Médico tratante';
  return `• Paciente: ${pacNombre} | Cama: ${camaCod} (${habTipo}, Planta ${planta}) | Motivo de ingreso: ${motivo} | Médico tratante: ${med}`;
});

// 4. Lab clínico activo y resumen de órdenes
const labSummary = metricasRaw.laboratorio || [];
const labPend = labSummary.find(l => l.estado === 'PENDIENTE')?.total || 0;
const labProc = labSummary.find(l => l.estado === 'EN_PROCESO')?.total || 0;
const labComp = labSummary.find(l => l.estado === 'COMPLETADO')?.total || 0;
const labCanc = labSummary.find(l => l.estado === 'CANCELADA')?.total || 0;
const labActivas = labPend + labProc;
const labTotal = labActivas + labComp + labCanc;

const labLines = lab.filter(l => ['PENDIENTE', 'EN_PROCESO'].includes(l.estado)).map(l => {
  return `• Examen: ${l.examen?.nombre || 'Prueba'} | Paciente: ${l.paciente?.nombre_completo || 'Paciente'} | Estado: ${l.estado}`;
});

// 5. Personal y Pacientes registrados
const totalColaboradores = metricasRaw.personal_activo || 0;
const totalPacientes = metricasRaw.pacientes || 0;

// 6. Ambulancia
const amb = metricasRaw.ambulancia || { estado: 'DISPONIBLE', servicios_mes: 0 };

const radiografia = `=== RADIOGRAFÍA OPERATIVA INMEDIATA (HOSPITAL CMO) ===

👥 PERSONAL Y PACIENTES REGISTRADOS EN EL SISTEMA:
• Colaboradores activos en hospital: Exactamente ${totalColaboradores} colaboradores (médicos, recepción, enfermería y administración).
• Pacientes registrados en sistema: Exactamente ${totalPacientes} pacientes con expediente clínico abierto.

🛏️ HOSPITALIZACIÓN Y OCUPACIÓN DE CAMAS:
• Planta 2 (Habitaciones Semiprivadas): ${p2Ocup} cama ocupada, ${p2Disp} camas libres disponibles (Total: ${p2Ocup + p2Disp} camas).
• Planta 3 (Suites VIP Individuales): ${p3Ocup} suites ocupadas, ${p3Disp} suites VIP libres disponibles (Total: ${p3Ocup + p3Disp} suites).
• Total global del hospital: ${p2Ocup + p3Ocup} cama ocupada, ${p2Disp + p3Disp} camas libres disponibles (Total general: ${p2Ocup + p3Ocup + p2Disp + p3Disp} camas).
• Detalle de internados actualmente en camas:
${internadosLines.length > 0 ? internadosLines.join('\n') : 'Sin pacientes internados actualmente en camas.'}

🚑 UNIDAD DE TRASLADO MÓVIL (AMBULANCIA):
• Estado actual: ${amb.estado}
• Servicios atendidos/completados este mes: ${amb.servicios_mes} servicio(s)
• Capacidad móvil instalada: Exactamente 1 ambulancia privada propia del hospital.

📦 INVENTARIO EN BODEGA CENTRAL (Total: ${recursos.length} ítems | Críticos bajo mínimo: ${stockCriticoCount}):
• MEDICAMENTOS:
${medBajosText}
  Con stock suficiente:
  ${medOptimos.join('\n  ')}

• INSUMOS MÉDICOS:
${insBajosText}
  Con stock suficiente:
  ${insOptimos.join('\n  ')}

• EQUIPOS MÉDICOS:
${eqBajosText}
  Con stock suficiente:
  ${eqOptimos.join('\n  ')}

🧪 LABORATORIO CLÍNICO:
• Órdenes activas en curso: ${labActivas} órdenes (${labPend} PENDIENTES, ${labProc} EN_PROCESO).
• Histórico y balance general: ${labComp} COMPLETADA, ${labCanc} CANCELADAS (Total histórico registrado: ${labTotal} órdenes).
• Detalle de órdenes activas:
${labLines.length > 0 ? labLines.join('\n') : 'Sin órdenes activas en curso.'}`;

const cleanHistory = Array.isArray(historial)
  ? historial.slice(-6).map(h => ({
      role: h.role === 'user' ? 'user' : 'assistant',
      content: String(h.content || '')
    }))
  : [];

const hoyStr = new Date().toISOString().split('T')[0];
const bearerToken = token.startsWith('Bearer ') ? token : `Bearer ${token}`;
const qLower = pregunta.toLowerCase();

// DETECCIÓN DE MÓDULO OBJETIVO PARA ENRUTAMIENTO DETERMINÍSTICO
let targetEndpoint = null;
let targetModule = null;

const isClinicalCorrelation = qLower.includes('ingresad') || qLower.includes('internad') || qLower.includes('hace falta') || qLower.includes('necesita');

if (!isClinicalCorrelation) {
  if (
    qLower.includes('turno') || qLower.includes('horario') || qLower.includes('jornada') || 
    qLower.includes('hora') || qLower.includes('carga laboral') || qLower.includes('promedio') || 
    qLower.includes('top') || qLower.includes('ranking') || qLower.includes('trabaja') ||
    qLower.includes('cubrir') || qLower.includes('cobertura') || qLower.includes('guardia')
  ) {
    targetModule = 'turnos';
    targetEndpoint = '/api/v1/turnos?per_page=100';
  } else if (qLower.includes('cita') || qLower.includes('agenda')) {
    targetModule = 'citas';
    targetEndpoint = '/api/v1/citas?per_page=60';
  } else if ((qLower.includes('médic') || qLower.includes('medic') || qLower.includes('doctor') || qLower.includes('especialista')) && !qLower.includes('medicamento')) {
    targetModule = 'medicos';
    targetEndpoint = '/api/v1/medicos';
  } else if (qLower.includes('consultorio')) {
    targetModule = 'consultorios';
    targetEndpoint = '/api/v1/consultorios';
  } else if (qLower.includes('aviso') || qLower.includes('comunicado')) {
    targetModule = 'avisos';
    targetEndpoint = '/api/v1/avisos';
  } else if (qLower.includes('bitácora') || qLower.includes('bitacora') || qLower.includes('traslado')) {
    targetModule = 'bitacora';
    targetEndpoint = '/api/v1/ambulancia/servicios';
  } else if (qLower.includes('catálogo') || qLower.includes('catalogo') || (qLower.includes('precio') && qLower.includes('examen'))) {
    targetModule = 'examenes';
    targetEndpoint = '/api/v1/examenes';
  } else if (qLower.includes('buscar paciente') || qLower.includes('directorio de paciente') || qLower.includes('lista de paciente')) {
    targetModule = 'pacientes';
    targetEndpoint = '/api/v1/pacientes';
  }
}

let contextBlock = '';

if (targetEndpoint) {
  try {
    const apiRes = await this.helpers.httpRequest({
      url: `http://192.168.110.200:8000${targetEndpoint}`,
      method: 'GET',
      headers: {
        'Authorization': bearerToken,
        'Accept': 'application/json'
      },
      json: true,
      timeout: 20000
    });

    let rawData = apiRes.data || [];
    if (rawData && rawData.data && Array.isArray(rawData.data)) {
      rawData = rawData.data;
    }
    const items = Array.isArray(rawData) ? rawData : [rawData];

    if (targetModule === 'turnos') {
      const stats = {};
      items.forEach(t => {
        const u = t.usuario || {};
        const rol = u.rol || 'PERSONAL';
        const nom = u.nombre_completo || 'Personal';
        if (rol !== 'MEDICO') return;

        if (!stats[nom]) {
          stats[nom] = {
            nombre: nom,
            cargo: u.cargo || 'Médico',
            totalTurnos: 0,
            totalHoras: 0,
            areas: new Set(),
            dias: new Set()
          };
        }
        stats[nom].totalTurnos += 1;
        stats[nom].areas.add(t.area || 'General');
        if (t.fecha) stats[nom].dias.add(t.fecha);

        if (t.hora_inicio && t.hora_fin) {
          const [h1, m1] = t.hora_inicio.split(':').map(Number);
          const [h2, m2] = t.hora_fin.split(':').map(Number);
          let dur = (h2 + (m2 || 0) / 60) - (h1 + (m1 || 0) / 60);
          if (dur < 0) dur += 24;
          stats[nom].totalHoras += dur;
        }
      });

      const medicosArr = Object.values(stats).sort((a, b) => b.totalHoras - a.totalHoras);

      let calcBlock = `=== MOTOR ALGEBRAICO EXACTO: REPORTE DE HORAS Y TURNOS ===\nTotal de médicos activos en el hospital: Exactamente ${medicosArr.length} médicos (${medicosArr.map(m => m.nombre).join(', ')}).\n\nDESGLOSE MATEMÁTICO DETERMINÍSTICO:\n`;
      medicosArr.forEach((m, idx) => {
        const prom = m.totalTurnos > 0 ? (m.totalHoras / m.totalTurnos).toFixed(1) : 0;
        calcBlock += `${idx + 1}. ${m.nombre} (${m.cargo}):\n   - Horas totales acumuladas: ${m.totalHoras.toFixed(1)} horas exactas\n   - Turnos laborados: ${m.totalTurnos} días\n   - Promedio por jornada: ${prom} horas/turno\n   - Áreas asignadas: ${Array.from(m.areas).join(', ')}\n`;
      });
      calcBlock += `\nRANKING DE CARGA HORARIA TOTAL:\n${medicosArr.map((m, idx) => `Puesto #${idx + 1}: ${m.nombre} (${m.totalHoras.toFixed(1)} horas)`).join('\n')}\n(Nota: Si piden Top 5 o Top 10, aclara que solo existen ${medicosArr.length} médicos en total en el hospital).\n\n`;

      const turnosHoy = items.filter(t => (t.fecha || '') === hoyStr);
      calcBlock += `TURNOS DE HOY (${hoyStr}):\n` + (turnosHoy.length > 0 
        ? turnosHoy.map(t => `- ${t.usuario?.nombre_completo || 'Personal'} (${t.usuario?.rol}): ${t.hora_inicio} a ${t.hora_fin} | Área: ${t.area}`).join('\n')
        : 'Sin turnos programados para hoy.');

      contextBlock = calcBlock;
    } else if (targetModule === 'citas') {
      const hoyCitas = items.filter(c => (c.fecha || '').startsWith(hoyStr));
      const atendidas = items.filter(c => c.estado === 'ATENDIDA').length;
      const agendadas = items.filter(c => c.estado === 'AGENDADA').length;
      const canceladas = items.filter(c => c.estado === 'CANCELADA').length;

      let calcCitas = `=== REPORTE DETERMINÍSTICO DE CITAS MÉDICAS ===\nTotal de citas en registro: ${items.length}\nCitas para hoy (${hoyStr}): ${hoyCitas.length}\nResumen por estado: Atendidas: ${atendidas} | Agendadas: ${agendadas} | Canceladas: ${canceladas}\n\n`;
      calcCitas += 'CITAS RECIENTES/PROGRAMADAS:\n' + items.slice(0, 15).map(c => 
        `- Fecha: ${c.fecha || ''} ${c.hora_inicio || ''} a ${c.hora_fin || ''} | Paciente: ${c.paciente?.nombre_completo || 'Paciente'} | Médico: ${c.medico?.nombre_completo || 'Médico'} | Estado: ${c.estado || ''} | Motivo: ${c.motivo || ''}`
      ).join('\n');
      contextBlock = calcCitas;
    } else if (targetModule === 'medicos') {
      contextBlock = '=== DIRECTORIO MÉDICO ACTIVO ===\n' + items.map(m =>
        `- ${m.nombre_completo || ''} | Cargo/Especialidad: ${m.cargo || m.especialidad || 'Medicina General'} | Estado: ${m.estado || 'ACTIVO'}`
      ).join('\n');
    } else if (targetModule === 'consultorios') {
      contextBlock = '=== CONSULTORIOS MÉDICOS ===\n' + items.map(cs =>
        `- ${cs.nombre || cs.codigo || ''} | Ubicación: ${cs.ubicacion || 'Planta 1'} | Estado: ${cs.estado || 'ACTIVO'}`
      ).join('\n');
    } else if (targetModule === 'avisos') {
      contextBlock = '=== AVISOS INSTITUCIONALES ===\n' + items.map(a =>
        `- ${a.titulo || ''} (${a.fecha || ''}): ${a.contenido || a.mensaje || ''}`
      ).join('\n');
    } else {
      contextBlock = `=== REGISTROS DE ${targetModule.toUpperCase()} ===\n` + JSON.stringify(items.slice(0, 15));
    }
  } catch (err) {
    contextBlock = `Error al consultar ${targetEndpoint}: ${err.message}`;
  }
} else {
  contextBlock = radiografia;
}

const systemPrompt = `Eres el Asistente Operativo de Dirección del Hospital CMO (Centro Médico de Occidente). Asistes al Administrador y Jefe de Operaciones.
Fecha actual del sistema: ${hoyStr}.

REGLAS FUNDAMENTALES Y GUARDRAILS DE SEGURIDAD INSTITUCIONAL:

1. MODO CONSULTA / SOLO LECTURA (CERO ALUCINACIÓN DE ACCIÓN):
   - Operas EXCLUSIVAMENTE en modo de consulta, diagnóstico y análisis operativo (Solo Lectura). No tienes facultades ni permisos de escritura en la base de datos.
   - Si el usuario te ordena ejecutar acciones que alteren el sistema (ej. "cancela la cita", "agenda a X paciente", "compra 50 cajas", "genera una orden de compra", "despide a X", "modifica un turno"):
     NUNCA finjas ni digas que realizaste la acción (PROHIBIDO decir "se ha generado la orden" o "cita cancelada").
     Aclara de forma directa que como copiloto de consulta no tienes permisos para ejecutar cambios en la base de datos, e indica el módulo oficial donde el usuario debe realizar la gestión (ej. módulo de Citas y Agenda, o Compras/Almacén).

2. LÍMITE DE RESPONSABILIDAD CLÍNICA (NO PRESCRIPCIÓN NI ALTA):
   - Tu rol se limita a reportar la información operativa del hospital.
   - NUNCA prescribas medicamentos, no valides dosis/posologías (mg, intervalos) ni autorices o aconsejes dar el alta médica a un paciente.
   - Ante preguntas sobre recetar o dar el alta: aclara que por protocolo institucional y seguridad del paciente, la prescripción farmacológica y el alta corresponden exclusivamente al criterio del médico tratante a cargo.

3. CORRELACIÓN CLÍNICA ENTRE INGRESADOS E INVENTARIO:
   - Si el usuario pregunta si los pacientes ingresados o internados necesitan los medicamentos o insumos en déficit (ej. Amoxicilina, Guantes):
     Revisa los motivos de ingreso de los pacientes actualmente internados y sus exámenes de laboratorio pendientes.
     Responde con criterio objetivo si según su condición (ej. observación general, pruebas rutinarias de orina o lípidos) su cuadro clínico actual requiere o no el consumo urgente de los ítems en déficit. NUNCA te laves las manos diciendo que no tienes diagnósticos si tienes los motivos de ingreso y exámenes visibles en tus datos operativos.

4. CERTEZA DE DATOS Y CONTEOS (PRESETS Y MÉTRICAS GLOBALES):
   - Utiliza SIEMPRE las cifras exactas provistas en la RADIOGRAFÍA OPERATIVA o en el reporte algebraico.
   - Para ocupación de camas, ambulancia, inventario crítico, órdenes de laboratorio, colaboradores activos y pacientes registrados:
     Reporta los números exactos de inmediato sin titubeos ni evasivas (NUNCA digas que no tienes acceso a nómina o a registros de usuarios si los totales están indicados en los datos provistos).

5. CERTEZA MATEMÁTICA Y TURNOS:
   - Si se trata de horas, turnos, cálculos o rankings, utiliza los datos exactos del reporte matemático provisto. NUNCA inventes números. Si el usuario pide un Top superior a los médicos existentes, aclara cuántos hay con certeza.

6. FORMATO Y ESTILO:
   - Inicia OBLIGATORIAMENTE con una etiqueta entre corchetes: [INFO], [ADVERTENCIA], [CRITICO] u [OPTIMO].
   - Máximo 1-2 párrafos o viñetas claras. Respuestas ejecutivas, directas y sin introducciones pomposas.
   - Lenguaje formal hospitalario institucional. Cero mención a servidores, IA o hardware.`;

const messages = [
  { role: "system", content: `${systemPrompt}\n\n${contextBlock}` },
  ...cleanHistory,
  { role: "user", content: pregunta }
];

const resp = await this.helpers.httpRequest({
  url: 'http://192.168.110.200:11434/api/chat',
  method: 'POST',
  body: {
    model: 'qwen3.5:9b',
    stream: false,
    think: false,
    keep_alive: '2h',
    messages: messages,
    options: { temperature: 0.1 }
  },
  json: true,
  timeout: 90000
});

const finalContent = resp.message?.content || 'Operación completada.';
return { json: { respuesta: finalContent } };
